package com.trough.hot;
import android.os.*;import java.io.File;import org.json.*;
/** Bounded supported-fighter grip/release check using production controls. */
final class HalfSwordGripCheck implements Runnable {
 final boolean recovered;long appliedBefore;final HalfSwordView view;final HalfSwordAimCheck input;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();int stage,steps,gripSteps,dropSteps;long reactions;double force,releaseDistance,x,y,z;JSONObject heldPose,dropPose;boolean pausedRelease;
 HalfSwordGripCheck(HalfSwordView v){view=v;appliedBefore=v.recoveredDropApplied;input=new HalfSwordAimCheck(v);File request=new File(v.getContext().getFilesDir(),"home/.trough/half-sword-recovered-drop-check-request");recovered=request.isFile()&&request.delete();}
 void start(){ui.postDelayed(this,150);}
 void need(boolean ok,String why)throws Exception{if(!ok)throw new Exception(why);}
 public void run(){try{need(SystemClock.uptimeMillis()-began<30000,"Grip check timeout");need(view.isAttachedToWindow()&&view.renderVisible,"Scene unavailable");
  switch(stage){
   case 0:if(recovered)need(!view.recoveredDropEnabled,"Recovered rules must default off");input.click("Training view");if(view.weaponHoldEnabled)input.click("Compliant hold · prototype");input.click("Reset physics");input.click("Stance support setup");stage=1;break;
   case 1:if(view.resetPending())break;need(view.requestCharacterStep(),"Initial step rejected");stage=2;break;
   case 2:if(view.characterBusy||view.characterSteps<1)break;need(view.characterAppliedStanceSupport,"Support missing");input.click("Run / pause");steps=view.characterSteps;stage=3;break;
   case 3:if(view.characterSteps-steps<60)break;input.observation();input.click("Compliant hold · prototype");input.aim(30,30);steps=view.characterSteps;reactions=view.weaponGripReactionFrames;stage=4;break;
   case 4:if(view.characterSteps-steps<120)break;heldPose=input.observation();force=Math.sqrt(view.weaponHandX*view.weaponHandX+view.weaponHandY*view.weaponHandY+view.weaponHandZ*view.weaponHandZ);need(view.weaponHeld&&!view.weaponReleased&&view.weaponGripSteps>=100,"Held body missing");need(Double.isFinite(force)&&force<=50.01&&view.weaponGripReactionFrames>reactions,"Grip force invalid or absent");input.click("Run / pause");input.pausedSteps=-1;stage=5;break;
   case 5:if(!input.pausedScene(true))break;if(recovered)saveScene("held");gripSteps=view.weaponGripSteps;x=view.weaponDropX;y=view.weaponDropY;z=view.weaponDropZ;if(recovered){appliedBefore=view.recoveredDropApplied;input.click("Recovered drop rules · approximate");need(!view.recoveredDropPending&&!view.weaponReleased,"Enabling rule applied without a physics step");steps=view.characterSteps;input.click("Run / pause");stage=11;}else{input.click("Release sword");stage=6;}break;
   case 6:if(view.characterBusy||!view.weaponReleased||view.weaponDropSteps<1)break;need(!view.characterRunning&&!view.weaponHeld&&view.weaponDropSteps==1,"Paused release advanced extra frames");need(Double.isFinite(view.weaponVelocityX)&&Double.isFinite(view.weaponVelocityY)&&Double.isFinite(view.weaponVelocityZ),"Invalid release velocity");pausedRelease=true;input.pausedSteps=-1;stage=7;break;
   case 7:if(!input.pausedScene(false))break;dropSteps=view.weaponDropSteps;input.click("Run / pause");steps=view.characterSteps;stage=8;break;
   case 8:if(view.characterSteps-steps<60)break;dropPose=input.observation();releaseDistance=Math.sqrt(Math.pow(view.weaponDropX-x,2)+Math.pow(view.weaponDropY-y,2)+Math.pow(view.weaponDropZ-z,2));need(view.weaponReleased&&!view.weaponHeld&&view.weaponDropSteps>dropSteps&&releaseDistance>.02,"Released weapon did not move independently");input.click("Run / pause");input.pausedSteps=-1;stage=9;break;
   case 9:if(!input.pausedScene(false))break;if(recovered)saveScene("released");dropSteps=view.weaponDropSteps;if(recovered){need(view.recoveredDropApplied==appliedBefore+1&&!view.weaponHoldEnabled,"Automatic drop repeated or reheld");input.click("Recovered drop rules · approximate");}else input.click("Compliant hold · prototype");input.click("Reset physics");stage=10;break;
   case 10:if(view.resetPending()||view.characterBusy)break;need(!view.characterRunning&&!view.weaponReleased&&!view.weaponHeld&&!view.weaponHoldEnabled&&view.weaponGripSteps==0&&view.weaponDropSteps==0,"Reset retained weapon state");finish(null);return;
   case 11:if(!view.weaponReleased||view.weaponHeld||view.weaponDropSteps<1){need(view.characterSteps-steps<120,"Recovered overload did not release");break;}need(view.recoveredDropApplied==appliedBefore+1&&!view.weaponHeld&&!view.weaponHoldEnabled,"Recovered release did not clean up hold");dropSteps=view.weaponDropSteps;steps=view.characterSteps;stage=8;break;
  }ui.postDelayed(this,100);
 }catch(Throwable error){view.characterRunning=false;view.cancelAllTouchInputs();finish(error.toString());}}
 void saveScene(String label)throws Exception{
  File home=new File(view.getContext().getFilesDir(),"home/.trough");JSONObject meta=new JSONObject(new String(Payloads.readSmall(new File(home,view.expanded?"half-sword-expanded-scene.json":"half-sword-preview-scene.json")),"UTF-8"));need(meta.getJSONObject("runtime").getInt("character_steps")==view.characterSteps,"Scene step mismatch");String name=meta.getString("image_file");need(name.equals(new File(name).getName())&&name.endsWith(".png"),"Invalid scene image path");File source=new File(home,name);need(source.length()>0&&source.length()<1048576,"Invalid scene image size");File target=new File(view.getContext().getFilesDir(),"work/trough-lab/half-sword/build/recovered-drop-live");target.mkdirs();java.io.FileInputStream in=new java.io.FileInputStream(source);java.io.FileOutputStream out=new java.io.FileOutputStream(new File(target,label+".png"));try{byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))>0)out.write(bytes,0,n);}finally{in.close();out.close();}meta.put("evidence_label",label);Payloads.writeSmall(new File(target,label+"-scene.json"),meta.toString());
 }
 void finish(String error){try{JSONObject out=new JSONObject();out.put("recovered_mode",recovered).put("recovered_drop_applied",view.recoveredDropApplied-appliedBefore);out.put("passed",error==null).put("error",error==null?"":error).put("stage",stage).put("held_observation",heldPose).put("released_observation",dropPose).put("hand_force_n",force).put("grip_steps",gripSteps).put("reaction_frames",view.weaponGripReactionFrames-reactions).put("released_steps",dropSteps).put("release_distance_m",releaseDistance).put("paused_single_release_step",pausedRelease).put("module",HalfSwordBridge.loadedModuleSha256).put("time_ms",System.currentTimeMillis()).put("scope",recovered?"Default-off control, no release on enable while paused, sustained prototype overload automatic release, independent drop motion, no rehold, disable and reset; approximate force/state mapping":"Supported native compliant hold/aim, bounded force, paused single-step release, independent movement, pause and reset; no damage or full combat claim");Payloads.writeSmall(new File(view.getContext().getFilesDir(),recovered?"home/.trough/half-sword-recovered-drop-check-result.json":"home/.trough/half-sword-grip-check-result.json"),out.toString());}catch(Exception failure){android.util.Log.e("Trough","Grip check result failed",failure);}}
}
